const PAGE_SIZE = 20;
let currentPage = 1;
let sortCol = '';
let sortAsc = true;
let filteredData = [...DATA.table];

const COLOR_MAP = {
  portrait: {
    '健康扩张': '#3B82F6', '成长期': '#60A5FA', '预警增长': '#93C5FD', '现金牛': '#A78BFA',
    '利润优化': '#2DD4BF', '主动收缩': '#6366F1', '夕阳产品': '#FB923C', '衰退期': '#F87171',
    '隐性衰退': '#F472B6', '新品观察': '#34D399', '清仓/偶发': '#94A3B8', '未知': '#9CA3AF'
  },
  risk: { '低风险': '#34D399', '中风险': '#FBBF24', '高风险': '#F87171', '暂无评分': '#9CA3AF' },
  summary: { '投入区': '#3B82F6', '维持区': '#34D399', '观察区': '#FBBF24', '退出区': '#F87171', '待观察': '#9CA3AF' },
  profit: { '健康': '#34D399', '轻度侵蚀': '#FBBF24', '严重侵蚀': '#F87171' },
  momentum: { '加速增长': '#3B82F6', '稳定扩张': '#34D399', '持平': '#FBBF24', '萎缩': '#F87171' }
};

function init() {
  populateFilters();
  updateKPI(DATA.table);
  renderCharts(DATA.table);
  renderTable();
  document.getElementById('header-total').textContent = DATA.kpi.total_products;
  document.getElementById('kpi-insufficient').textContent = DATA.kpi.data_insufficient;
}

function populateFilters() {
  const opts = DATA.filters;
  const sel = (id, items) => {
    const el = document.getElementById(id);
    items.forEach(v => { const o = document.createElement('option'); o.value = v; o.textContent = v; el.appendChild(o); });
  };
  sel('filter-portrait', opts.portrait);
  sel('filter-risk', opts.risk);
  sel('filter-pareto', opts.pareto);
  sel('filter-group', opts.group);
  sel('filter-momentum', opts.momentum);
  sel('filter-profit', opts.profit);
  sel('filter-summary', opts.summary);
}

function applyFilters() {
  const search = document.getElementById('search-input').value.toLowerCase();
  const f = {
    portrait: document.getElementById('filter-portrait').value,
    risk: document.getElementById('filter-risk').value,
    pareto: document.getElementById('filter-pareto').value,
    group: document.getElementById('filter-group').value,
    momentum: document.getElementById('filter-momentum').value,
    profit: document.getElementById('filter-profit').value,
    summary: document.getElementById('filter-summary').value,
  };

  filteredData = DATA.table.filter(row => {
    if (search && !row['产品名称'].toLowerCase().includes(search)) return false;
    if (f.portrait && row['当前画像'] !== f.portrait) return false;
    if (f.risk && row['衰退风险等级'] !== f.risk) return false;
    if (f.pareto && row['帕累托分类'] !== f.pareto) return false;
    if (f.group && row['所属参照组'] !== f.group) return false;
    if (f.momentum && row['销量动能'] !== f.momentum) return false;
    if (f.profit && row['盈利健康'] !== f.profit) return false;
    if (f.summary && row['管理层摘要'] !== f.summary) return false;
    return true;
  });

  currentPage = 1;
  updateKPI(filteredData);
  renderCharts(filteredData);
  renderTable();
  updateActiveFilters(f);
}

function updateActiveFilters(f) {
  const container = document.getElementById('active-filters');
  const labels = { portrait: '画像', risk: '风险', pareto: '分类', group: '参照组', momentum: '动能', profit: '盈利', summary: '摘要' };
  let html = '';
  Object.entries(f).forEach(([k, v]) => {
    if (v) html += `<span class="filter-chip">${labels[k]}: ${v} <span class="close" onclick="clearFilter('filter-${k}')">&times;</span></span>`;
  });
  container.innerHTML = html || '<span class="text-xs text-gray-400">无活跃筛选条件</span>';
}

function clearFilter(id) {
  document.getElementById(id).value = '';
  applyFilters();
}

function resetAll() {
  document.getElementById('search-input').value = '';
  ['filter-portrait','filter-risk','filter-pareto','filter-group','filter-momentum','filter-profit','filter-summary'].forEach(id => {
    document.getElementById(id).value = '';
  });
  applyFilters();
}

function updateKPI(rows) {
  const highRisk = rows.filter(r => r['衰退风险等级'] === '高风险').length;
  const declining = rows.filter(r => ['衰退期','夕阳产品','隐性衰退'].includes(r['当前画像'])).length;
  const growing = rows.filter(r => ['成长期','健康扩张','预警增长'].includes(r['当前画像'])).length;
  const gmSum = rows.reduce((s, r) => s + (parseFloat(r['近12月毛利率%']) || 0) * (parseFloat(r['近12月销量']) || 0), 0);
  const salesSum = rows.reduce((s, r) => s + (parseFloat(r['近12月销量']) || 0), 0);
  const avgGm = salesSum ? (gmSum / salesSum).toFixed(1) : 0;
  const avgGrowth = rows.length ? (rows.reduce((s, r) => s + (parseFloat(r['近12月增长率%']) || 0), 0) / rows.length).toFixed(1) : 0;

  document.getElementById('kpi-total').textContent = rows.length;
  document.getElementById('kpi-high-risk').textContent = highRisk;
  document.getElementById('kpi-declining').textContent = declining;
  document.getElementById('kpi-growing').textContent = growing;
  document.getElementById('kpi-avg-gm').textContent = avgGm + '%';
  document.getElementById('kpi-avg-growth').textContent = avgGrowth + '%';
  const insufficient = rows.filter(r => r['数据不足']).length;
  document.getElementById('kpi-insufficient').textContent = insufficient;
}

function renderCharts(rows) {
  renderPortraitChart(rows);
  renderRiskChart(rows);
  renderParetoChart(rows);
  renderSummaryChart(rows);
  renderSlopeChart(rows);
  renderMatrixChart(rows);
  renderScatterChart(rows);
  renderSankeyChart(rows);
  renderRFMChart();
  renderNetworkChart();
  renderRiskHistChart(rows);
}

function renderPortraitChart(rows) {
  const counts = {};
  rows.forEach(r => { const v = r['当前画像'] || '未知'; counts[v] = (counts[v] || 0) + 1; });
  const data = Object.entries(counts).map(([name, value]) => ({ name, value, itemStyle: { color: COLOR_MAP.portrait[name] || '#9ca3af' } }));
  const chart = echarts.init(document.getElementById('chart-portrait'));
  chart.setOption({
    tooltip: { trigger: 'item', formatter: '{b}: {c} ({d}%)' },
    legend: { type: 'scroll', bottom: 0, textStyle: { fontSize: 11 } },
    series: [{
      type: 'pie', radius: ['25%', '55%'], center: ['50%', '42%'],
      avoidLabelOverlap: true,
      itemStyle: { borderRadius: 6, borderColor: '#fff', borderWidth: 2 },
      label: { show: false },
      emphasis: { label: { show: true, fontSize: 14, fontWeight: 'bold' } },
      data
    }]
  });
  chart.on('click', params => { document.getElementById('filter-portrait').value = params.name; applyFilters(); });
}

function renderRiskChart(rows) {
  const counts = {};
  rows.forEach(r => { const v = r['衰退风险等级'] || '暂无评分'; counts[v] = (counts[v] || 0) + 1; });
  const data = Object.entries(counts).map(([name, value]) => ({ name, value, itemStyle: { color: COLOR_MAP.risk[name] || '#9ca3af' } }));
  const chart = echarts.init(document.getElementById('chart-risk'));
  chart.setOption({
    tooltip: { trigger: 'item', formatter: '{b}: {c} ({d}%)' },
    legend: { bottom: 0, textStyle: { fontSize: 11 } },
    series: [{
      type: 'pie', radius: '55%', center: ['50%', '42%'],
      itemStyle: { borderRadius: 6, borderColor: '#fff', borderWidth: 2 },
      label: { formatter: '{b}\n{c}' },
      data
    }]
  });
  chart.on('click', params => { document.getElementById('filter-risk').value = params.name; applyFilters(); });
}


function renderRFMChart() {
  var chart = echarts.init(document.getElementById('chart-rfm'));
  if (typeof DATA.rfm === 'undefined' || !DATA.rfm) {
    chart.setOption({ title: { text: '暂无RFM数据', left: 'center', top: 'center', textStyle: { color: '#9CA3AF', fontSize: 14 } } });
    return;
  }
  var entries = Object.entries(DATA.rfm);
  var palette = ['#3B82F6','#60A5FA','#93C5FD','#A78BFA','#34D399','#FBBF24','#F87171','#2DD4BF','#F472B6','#FB923C'];
  var data = entries.map(function(e, i) { return { name: e[0], value: e[1], itemStyle: { color: palette[i % palette.length] } }; });
  chart.setOption({
    tooltip: { trigger: 'item', formatter: '{b}: {c} ({d}%)' },
    legend: { type: 'scroll', bottom: 0, textStyle: { fontSize: 11 } },
    series: [{ type: 'pie', radius: ['25%', '55%'], center: ['50%', '42%'], avoidLabelOverlap: true,
      itemStyle: { borderRadius: 6, borderColor: '#fff', borderWidth: 2 },
      label: { show: false }, emphasis: { label: { show: true, fontSize: 14, fontWeight: 'bold' } }, data: data }]
  });
}

function renderNetworkChart() {
  var chart = echarts.init(document.getElementById('chart-network'));
  var graph = DATA.graph;
  if (!graph || !graph.nodes || graph.nodes.length === 0) {
    chart.setOption({ title: { text: '暂无关联数据', left: 'center', top: 'center', textStyle: { color: '#9CA3AF', fontSize: 14 } } });
    return;
  }
  chart.setOption({
    tooltip: { formatter: function(p) {
      if (p.dataType === 'edge') return '<b>' + p.data.source + '</b> &harr; <b>' + p.data.target + '</b><br/>支持度: ' + p.data.support + '<br/>置信度: ' + p.data.confidence;
      return '<b>' + p.name + '</b><br/>关联产品数: ' + p.value;
    } },
    series: [{ type: 'graph', layout: 'force', force: { repulsion: 200, edgeLength: [80, 200], friction: 0.08, layoutAnimation: false },
      roam: true, draggable: true, symbolSize: function(d) { return Math.max(10, Math.min(d.value * 4, 30)); },
      label: { show: true, fontSize: 9, position: 'bottom' },
      lineStyle: { color: '#93C5FD', width: function(d) { return Math.max(1.5, d.support * 6); }, opacity: 0.7, curveness: 0.1 },
      data: graph.nodes, links: graph.links,
      itemStyle: { color: '#3B82F6', borderColor: '#FFFFFF', borderWidth: 1.5 } }]
  });
}

function renderRiskHistChart(rows) {
  var scores = rows.map(function(r) { return parseFloat(r['\u8870\u9000\u98CE\u9669\u5F97\u5206']) || 0; }).filter(function(v) { return v > 0; });
  var bins = { '0-20': 0, '21-40': 0, '41-60': 0, '61-80': 0, '81-100': 0 };
  scores.forEach(function(v) {
    if (v <= 20) bins['0-20']++; else if (v <= 40) bins['21-40']++; else if (v <= 60) bins['41-60']++; else if (v <= 80) bins['61-80']++; else bins['81-100']++;
  });
  var colors = ['#34D399', '#93C5FD', '#FBBF24', '#FB923C', '#F87171'];
  var chart = echarts.init(document.getElementById('chart-risk-hist'));
  chart.setOption({
    tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' }, formatter: function(p) { return p[0].name + '\u5206: ' + p[0].value + '\u4E2A\u4EA7\u54C1'; } },
    grid: { left: 50, right: 20, top: 20, bottom: 40 },
    xAxis: { type: 'category', data: Object.keys(bins), axisLabel: { fontSize: 11 } },
    yAxis: { type: 'value', name: '\u4EA7\u54C1\u6570', splitLine: { lineStyle: { type: 'dashed' } } },
    series: [{ type: 'bar', barWidth: '60%', data: Object.values(bins).map(function(v, i) { return { value: v, itemStyle: { color: colors[i] } }; }),
      label: { show: true, position: 'top', fontSize: 11 } }]
  });
}


