function renderMatrixChart(rows) {
  const matrix = {};
  const profits = ['健康', '轻度侵蚀', '严重侵蚀'];
  const momentums = ['加速增长', '稳定扩张', '持平', '萎缩'];
  profits.forEach(p => { matrix[p] = {}; momentums.forEach(m => matrix[p][m] = 0); });
  rows.forEach(r => { const p = r['盈利健康'], m = r['销量动能']; if (matrix[p] && matrix[p][m] !== undefined) matrix[p][m]++; });
  const series = momentums.map(m => ({
    name: m, type: 'bar', stack: 'total',
    itemStyle: { color: COLOR_MAP.momentum[m] },
    data: profits.map(p => matrix[p][m] || 0)
  }));
  const chart = echarts.init(document.getElementById('chart-matrix'));
  chart.setOption({
    tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },
    legend: { bottom: 0, textStyle: { fontSize: 11 } },
    grid: { left: 50, right: 20, top: 20, bottom: 50 },
    xAxis: { type: 'category', data: profits, axisLabel: { fontSize: 11 } },
    yAxis: { type: 'value', name: '产品数' },
