function renderSlopeChart(rows) {
  const slopeData = rows.map(r => parseFloat(r['毛利率趋势斜率%/月']) || 0).filter(v => v !== 0);
  const bins = { '< -1%': 0, '-1% ~ -0.5%': 0, '-0.5% ~ -0.1%': 0, '-0.1% ~ 0.1%': 0, '0.1% ~ 0.5%': 0, '0.5% ~ 1%': 0, '> 1%': 0 };
  slopeData.forEach(v => {
    if (v < -1) bins['< -1%']++;
    else if (v < -0.5) bins['-1% ~ -0.5%']++;
    else if (v < -0.1) bins['-0.5% ~ -0.1%']++;
    else if (v < 0.1) bins['-0.1% ~ 0.1%']++;
    else if (v < 0.5) bins['0.1% ~ 0.5%']++;
    else if (v < 1) bins['0.5% ~ 1%']++;
    else bins['> 1%']++;
  });
  const colors = ['#ef4444', '#f97316', '#f59e0b', '#9ca3af', '#10b981', '#06b6d4', '#3b82f6'];
  const categories = Object.keys(bins);
  const values = Object.values(bins);
  const chart = echarts.init(document.getElementById('chart-slope'));
  chart.setOption({
    tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },
    grid: { left: 100, right: 20, top: 20, bottom: 40 },
    xAxis: { type: 'value', name: '产品数' },
    yAxis: { type: 'category', data: categories.reverse(), axisLabel: { fontSize: 11 } },
    series: [{
      type: 'bar',
      data: values.reverse().map((v, i) => ({ value: v, itemStyle: { color: colors[colors.length - 1 - i] } })),
      label: { show: true, position: 'right', fontSize: 11 }
    }]
  });
}


function removeSankeyCycles(nodes, links) {
  const nodeNames = nodes.map(function(n) { return n.name; });
  const adj = {};
  nodeNames.forEach(function(n) { adj[n] = []; });
  links.forEach(function(l) { if (!adj[l.source]) adj[l.source] = []; adj[l.source].push(l.target); });
  var WHITE = 0, GRAY = 1, BLACK = 2;
  var color = {};
  nodeNames.forEach(function(n) { color[n] = WHITE; });
  var backEdges = [];
  function dfs(node) {
    color[node] = GRAY;
    if (adj[node]) {
      for (var i = 0; i < adj[node].length; i++) {
        var neighbor = adj[node][i];
        if (color[neighbor] === GRAY) {
          backEdges.push({source: node, target: neighbor});
        } else if (color[neighbor] === WHITE) {
          dfs(neighbor);
        }
      }
    }
    color[node] = BLACK;
  }
  nodeNames.forEach(function(n) { if (color[n] === WHITE) dfs(n); });
  return links.filter(function(l) {
    return !backEdges.some(function(be) { return be.source === l.source && be.target === l.target; });
  });
}

function renderSankeyChart(rows) {
  const sd = DATA.sankey;
  if (!sd || !sd.nodes || !sd.links) return;
  const acyclicLinks = removeSankeyCycles(sd.nodes, sd.links);
  const pc = {
    '新品观察': '#84cc16', '成长期': '#3b82f6',
    '健康扩张': '#10b981', '预警增长': '#f59e0b',
    '现金牛': '#8b5cf6', '利润优化': '#06b6d4',
    '隐性衰退': '#ec4899', '主动收缩': '#6366f1',
    '衰退期': '#ef4444', '夕阳产品': '#f97316',
    '清仓/偶发': '#6b7280'
  };
  const chart = echarts.init(document.getElementById('chart-sankey'));
  // Color nodes by portrait type
  const coloredNodes = sd.nodes.map(n => {
    const label = n.name.split('_')[1];
    return { ...n, itemStyle: { color: pc[label] || '#9ca3af' } };
  });
  // Color links by source node color with transparency
  const coloredLinks = acyclicLinks.map(l => {
    const srcLabel = l.source.split('_')[1];
    const baseColor = pc[srcLabel] || '#999';
    return { ...l, lineStyle: { color: baseColor, opacity: 0.35, curveness: 0.5 } };
  });
  chart.setOption({
    tooltip: {
      trigger: 'item',
      formatter: p => {
        if (p.dataType === 'edge') {
          const prods = p.data.products || [];
          const top5 = prods.slice(0, 20).join('<br/>');
          const more = prods.length > 20 ? '<br/>...共' + prods.length + '个产品' : '';
          return '<b>' + p.data.source.split('_')[1] + ' → ' + p.data.target.split('_')[1] + '</b><br/>产品数: ' + p.data.value + '<br/><br/>' + top5 + more;
        }
        var parts = p.name.split('_');
        var prods = p.data.products || [];
        var top8 = prods.slice(0, 30).join('<br/>');
        var more = prods.length > 30 ? '<br/>...共' + prods.length + '个产品' : '';
        return '<b>' + parts[0] + ' · ' + parts[1] + '</b><br/>产品数: ' + prods.length + '<br/><br/>' + top8 + more;
      }
    },
    series: [{
      type: 'sankey',
      layout: 'none',
      left: 30, right: 120, top: 15, bottom: 15,
      nodeWidth: 14,
      nodeGap: 6,
      nodeAlign: 'left',
      data: coloredNodes,
      links: coloredLinks,
      lineStyle: { curveness: 0.5 },
      label: {
        show: true,
        position: 'right',
        fontSize: 12,
        formatter: function(p) { return p.name.split('_')[1]; }
      },
      emphasis: {
        focus: 'adjacency',
        lineStyle: { opacity: 0.7 }
      }
    }]
  });
}function sortTable(col) {
  if (sortCol === col) sortAsc = !sortAsc;
  else { sortCol = col; sortAsc = true; }
  filteredData.sort((a, b) => {
    let av = a[col], bv = b[col];
    if (!isNaN(parseFloat(av)) && av !== '' && !isNaN(parseFloat(bv)) && bv !== '') { av = parseFloat(av); bv = parseFloat(bv); }
    if (av === '' || av === null) return 1; if (bv === '' || bv === null) return -1;
    return sortAsc ? (av > bv ? 1 : -1) : (av < bv ? 1 : -1);
  });
  renderTable();
}

function renderTable() {
  const tbody = document.getElementById('table-body');
  const start = (currentPage - 1) * PAGE_SIZE;
  const pageData = filteredData.slice(start, start + PAGE_SIZE);

  tbody.innerHTML = pageData.map(row => `
    <tr class="table-row fade-in" onclick="openDetail('${row['产品名称']}')">
      <td class="px-4 py-3 font-medium text-gray-900 col-name" title="${row['产品名称']}">${row['产品名称']}${row['数据不足'] ? ' <span class="tag tag-sm" style="background:#fef3c7;color:#92400e">数据不足</span>' : ''}</td>
      <td class="px-4 py-3 text-gray-600 col-group" title="${row['所属参照组']}">${row['所属参照组']}</td>
      <td class="px-4 py-3 col-pareto"><span class="tag tag-sm" style="background:#f3f4f6;color:#374151">${row['帕累托分类']}</span></td>
      <td class="px-4 py-3"><span class="tag" style="background:${COLOR_MAP.portrait[row['当前画像']] || '#f3f4f6'}20;color:${COLOR_MAP.portrait[row['当前画像']] || '#6b7280'};border:1px solid ${COLOR_MAP.portrait[row['当前画像']] || '#e5e7eb'}80">${row['当前画像']}</span></td>
      <td class="px-4 py-3"><span class="tag tag-sm" style="background:${COLOR_MAP.summary[row['管理层摘要']] || '#f3f4f6'}20;color:${COLOR_MAP.summary[row['管理层摘要']] || '#6b7280'}">${row['管理层摘要']}</span></td>
      <td class="px-4 py-3 text-right font-mono text-gray-700">${formatNum(row['近12月销量'])}</td>
      <td class="px-4 py-3 text-right font-mono ${getGrowthColor(row['近12月增长率%'])}">${formatPct(row['近12月增长率%'])}</td>
      <td class="px-4 py-3 text-right font-mono">${formatPct(row['近12月毛利率%'])}</td>
      <td class="px-4 py-3 text-right font-mono ${getSlopeColor(row['毛利率趋势斜率%/月'])}">${formatSlope(row['毛利率趋势斜率%/月'])}</td>
      <td class="px-4 py-3 text-right font-mono font-medium">${row['衰退风险得分']}</td>
      <td class="px-4 py-3"><span class="tag" style="background:${COLOR_MAP.risk[row['衰退风险等级']] || '#f3f4f6'}20;color:${COLOR_MAP.risk[row['衰退风险等级']] || '#6b7280'};border:1px solid ${COLOR_MAP.risk[row['衰退风险等级']] || '#e5e7eb'}80">${row['衰退风险等级']}</span></td>
      <td class="px-4 py-3 text-gray-500 col-strategy" title="${row['通用策略建议']}">${row['通用策略建议'] || '-'}</td>
    </tr>
  `).join('');

  const totalPages = Math.ceil(filteredData.length / PAGE_SIZE) || 1;
  document.getElementById('table-info').textContent = `显示 ${filteredData.length} 条`;
  document.getElementById('page-info').textContent = `${currentPage} / ${totalPages}`;
}

function changePage(dir) {
  const totalPages = Math.ceil(filteredData.length / PAGE_SIZE) || 1;
  currentPage = Math.max(1, Math.min(totalPages, currentPage + dir));
  renderTable();
}

function formatNum(v) { if (!v && v !== 0) return '-'; return parseFloat(v).toLocaleString('zh-CN', {maximumFractionDigits:0}); }
function formatPct(v) { if (!v && v !== 0) return '-'; return parseFloat(v).toFixed(1) + '%'; }
function formatSlope(v) { if (!v && v !== 0) return '-'; const n = parseFloat(v); return (n > 0 ? '+' : '') + n.toFixed(2); }
function getGrowthColor(v) { if (!v) return 'text-gray-400'; const n = parseFloat(v); return n > 0 ? 'text-emerald-600' : n < 0 ? 'text-red-600' : 'text-gray-600'; }
function getSlopeColor(v) { if (!v) return 'text-gray-400'; const n = parseFloat(v); return n > 0 ? 'text-emerald-600' : n < 0 ? 'text-red-600' : 'text-gray-600'; }

function openDetail(name) {
