function closeDrawer() {
  document.getElementById('detail-drawer').classList.remove('open');
  document.getElementById('drawer-overlay').classList.remove('open');
}

function exportCSV() {
  const headers = Object.keys(filteredData[0] || {});
  const csv = [headers.join(','), ...filteredData.map(row => headers.map(h => `"${(row[h] || '').toString().replace(/"/g, '""')}"`).join(','))].join('\n');
  const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = `产品快照_${new Date().toISOString().slice(0,10)}.csv`;
  link.click();
}

window.addEventListener('resize', () => {
  ['chart-portrait','chart-risk','chart-pareto','chart-summary','chart-slope','chart-matrix','chart-scatter','chart-sankey','chart-rfm','chart-network','chart-risk-hist'].forEach(id => {
    const el = document.getElementById(id);
    if (el) echarts.getInstanceByDom(el)?.resize();
  });
});

init();

